"""Retain a terminal frozen cohort, including unsuccessful discovery controls."""
from pathlib import Path
import argparse,hashlib,json,shutil,subprocess
p=argparse.ArgumentParser();p.add_argument('--source',type=Path,default=Path('build/v8-variable-power-cases/corpus'));p.add_argument('--name',default='corpus-variable-power');p.add_argument('--session',type=int,required=True);a=p.parse_args();assert'/'not in a.name and'..'not in a.name
source=a.source;out=Path('bench/v8-learning')/a.name;report=json.loads((source/'report.json').read_bytes());records=json.loads((source/'records.json').read_bytes());assert len(records)==10 and all(r['status']==0 for r in records);assert report['context']==json.loads((source/'context.json').read_bytes());shutil.copytree(source,out);shutil.copyfile(source.parent/(source.name+'.log'),out/'driver.log')
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
(out/'terminal.json').write_text(json.dumps(dict(schema=1,exit_status=0,observed_session=a.session,programs=10,final_source_context_check_passed=True,report_sha256=sha(out/'report.json')),indent=2)+'\n')
git=lambda path,*args:subprocess.check_output(['git','-C',str(path),*args],text=True).strip()
(out/'source-pins.json').write_text(json.dumps(dict(schema=1,distribution_source=git('.','rev-parse','HEAD'),knowledge_before=git('knowledge','rev-parse','HEAD'),planner=git('planner','rev-parse','HEAD'),compiler_sha256=report['context']['compiler_sha256'],producer_source_sha256=report['context']['producer_source_sha256'],scope='Exact independently frozen compiler and current producer/proof bytes, complete private publications and final stable context. Wall-time bounded shared-host discovery is an observation, never proof, applicability or a causal performance comparison.'),indent=2)+'\n')
(out/'storage-retention.json').write_text(json.dumps(dict(schema=1,keep=[dict(path='.',reason='Completed required frozen corpus exact original inputs, complete checked plans, final context and terminal receipt, including unfavourable discovery outcomes. Private stores/targets omitted.')],safe_to_remove=[]),indent=2)+'\n')
index={str(p.relative_to(out)):sha(p)for p in sorted(out.rglob('*'))if p.is_file()};(out/'sha256-index.json').write_text(json.dumps(dict(schema=1,files=index),indent=2)+'\n')
summary=dict(schema=1,headline=report['headline'],near_misses=report['near_misses'],context=report['context'],scope='Unchanged frozen ten-program manifest and quick budgets; source captured before laws aimed at these programs. Private publication preparation excluded from recorded per-program interval; shared-host times are not causal comparisons.')
Path('bench/v8-learning',a.name+'-summary.json').write_text(json.dumps(summary,indent=2)+'\n');print(json.dumps(report['headline']))
